use snn_core::Fix32;
use snn_core::traits::SpikingNetwork;

// Inclusion of AOT model generated by NIR compiler
#[path = "common/generated_model.rs"]
mod generated_model;

#[test]
fn test_aot_generated_network_execution() {
    let mut network = generated_model::GeneratedNetwork::new();

    // 4 continuous input channels
    let inputs = [
        Fix32::from_num(1.5),
        Fix32::from_num(0.5),
        Fix32::from_num(-0.2),
        Fix32::from_num(2.0),
    ];

    // Execution of 10 ticks without allocation
    for tick in 0..10 {
        let spikes = network.tick(&inputs);
        assert_eq!(spikes.len(), 2, "Final layer must produce 2 neurons");
        if tick == 0 {
            // At initial tick with strong inputs, neurons should respond
            // either with a spike or sub-threshold integration
        }
    }

    // Network reset
    network.reset();
    assert_eq!(network.output_spikes, [false; 2]);
}

#[test]
fn test_aot_generated_model_descriptor_execution() {
    let model = &generated_model::MODEL_DESC;
    let mut sram = [0u8; 512];
    let mut ctx = model.init_context(&mut sram).expect("Valid SRAM context");

    let inputs = [
        Fix32::from_num(1.5),
        Fix32::from_num(0.5),
        Fix32::from_num(-0.2),
        Fix32::from_num(2.0),
    ];
    let mut out_spikes = [0u32; 1];

    for _ in 0..10 {
        model
            .step(&mut ctx, &inputs, &mut out_spikes)
            .expect("Step succeeded");
    }

    model.reset(&mut ctx);
}
